function NoticeDialog:OnShow()
    return CoWaitDo(function()
        ---@type UGUI.Effects.UIEffectCapturedImage
        --local capture = KTool.GetComponent(self.controller.gameObject, typeof(UIEffectCapturedImage))
        --if not isNull(capture) then
        --    capture:Capture()
        --end
        --KTool.SetRenderFeatureActiveByName("KawaseBlurRenderFeature", true)

        -- 解析参数
        local argument   = self.controller.Argument
        local customUrl  = nil
        local customPath = nil
        if isSet(argument, "parameters") then
            if isSet(argument.parameters, "url") then
                customUrl = checkString(argument.parameters.url)
            else
                customPath = checkString(argument.parameters.path)
            end
        end

        ------------------------------------------------- [Vuplex WebView]
        if self:IsUsedVuplexWebView() then
            local go = KTool.GetComponent(self.ViplexWebViewNode.gameObject,typeof(CS.ZenFulcrum.EmbeddedBrowser.Browser))
            KTool.SetActive(self.Webview.gameObject, false)
			KTool.SetActive(self.ViplexWebViewNode.gameObject, true)
           -- KTool.SetParent(go.gameObject, self.ViplexWebViewNode.gameObject, false)
			if go ~= nil then
                go:WhenLoaded(function()
                    KTool.SetActive(self.LoadingSign.gameObject, false)
                end)

				if customUrl then
					go:LoadURL(customUrl)
					go.Zoom = 1
				elseif customPath then
					self:DoLoadLocalHtml(customPath, function(bytes)
						go:LoadHTML(bytes)
						go.Zoom = 0.5
					end)
				else
					go:LoadURL(self:GetNoticeUrl())
					go.Zoom = 0.5
				end
			end
			
        ------------------------------------------------- [UniWebView]
        else
            self.Webview:Initialize()
            
            ---确保加载完才显示webview界面
            self.Webview._onLoadComplete = function()
                KTool.SetActive(self.LoadingSign.gameObject, false)
                -- self.Webview:Show()

                local uniWebview = KTool.GetComponent(self.Webview.gameObject, typeof(CS.UniWebView))
                if isNotNull(uniWebview) then
                    uniWebview:_Show(false, CS.UniWebViewTransitionEdge.None, 0.4, true) --调用异步接口显示，否则网页存在问题时会导致主线程卡住
                end
            end

            if customUrl then
                self.Webview:Load(customUrl)
            elseif customPath then
                self:DoLoadLocalHtml(customPath, function(bytes)
                    self.Webview:LoadHTMLString(bytes, "http://localhost/")
                end)
            else
                self.Webview:Load(self:GetNoticeUrl())
            end
        end
    end)
end


---@return boolean
function NoticeDialog:IsUsedVuplexWebView()
    if Application.platform == RuntimePlatform.WindowsPlayer or Application.platform == RuntimePlatform.OSXPlayer then
        return true
    elseif Application.platform == RuntimePlatform.WindowsEditor or Application.platform == RuntimePlatform.OSXEditor then
        local BuildTarget = CS.UnityEditor.BuildTarget
        local enabledList = {
            BuildTarget.StandaloneOSXUniversal,
            BuildTarget.StandaloneOSXIntel,
            BuildTarget.StandaloneOSXIntel64,
            BuildTarget.StandaloneOSX,
            BuildTarget.StandaloneWindows64,
            BuildTarget.StandaloneWindows,
        }
        local activeBuildTarget = CS.UnityEditor.EditorUserBuildSettings.activeBuildTarget
        for _, target in ipairs(enabledList) do
            if activeBuildTarget == target then
                return true
            end
        end
    end
    return false
end


---@param path string
---@param loadedCb fun(bytes:System.Byte):void
function NoticeDialog:DoLoadLocalHtml(path, loadedCb)
    self._co = CoStart(function()
        ---说明文档的类型
        local loader = HotBytesLoader.Load('Lua/html/' .. path, 0)
        while not loader.IsSuccess do
            CoYield()
        end
        if not loader.IsError then
            if loadedCb then
                loadedCb(loader.Bytes)
            end
        end
    end)
end


---@return string
function NoticeDialog:GetNoticeUrl()
    local commonParam = HttpModule.RequestBodyMeta:ToDictionary()
    local url = string.format('https://notice-%s/index.html?api=%s', HttpModule.ServerHost, HttpModule.ServerHost)
    for k, v in pairs(commonParam) do
        url = string.format('%s&%s=%s', url, string.url_encode(k), string.url_encode(tostring(v)))
    end
    return url
end



function NoticeDialog:OnInitialize()
    return CoWaitDo(function()
    end)
end


function NoticeDialog:OnFinalize()
    return CoWaitDo(function()
        if not isNull(self) then
            if self._co then
                CoStop(self._co)
                self._co = nil
            end
        end
        Events.Broadcast("OPEN_NOTICE_VIEW_CLOSE")
        CfUtils.CookieSave("OPEN_SIGN_VIEW", 1)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end)
end

return NoticeDialog